const {createWsuPortal}=require('redbox-hook-wsu/deployment');
const {REDBOX_APPLICATION_CONFIG,...env}=process.env;
const log=Object.fromEntries(['info','warn','error','debug','trace','verbose','silly','fatal','crit','log','blank','silent'].map(k=>[k,()=>{}]));
let portal;
(async()=>{portal=await createWsuPortal({appPath:process.cwd(),files:{application:REDBOX_APPLICATION_CONFIG},env,log});await portal.host.initialize();await portal.host.activate();console.log('diagnostic: activated');await portal.host.stop();process.exit(0);})().catch(async e=>{console.log(JSON.stringify({name:e.name,code:e.code,message:String(e.message).replace(/mongodb:\/\/[^\s]+/g,'<local-mongo>'),stack:String(e.stack).split('\n').slice(1,6)}));try{await portal?.host.stop()}catch{}process.exit(1)});

